'use strict';

/**
 * Session check shared by every authenticated route.
 * Sessions live in process.env.SESSIONS_TABLE keyed by the SHA-256 hex of the bearer token.
 */

const crypto = require('crypto');
const { GetCommand } = require('@aws-sdk/lib-dynamodb');
const { doc } = require('../database');
const { unauthorized } = require('../errors');

const BEARER = /^Bearer\s+(\S+)\s*$/i;

function hashToken(token) {
    return crypto.createHash('sha256').update(token, 'utf8').digest('hex');
}

/** Returns the raw bearer token from the Authorization header (any case), or null. */
function readBearerToken(event) {
    const headers = (event && event.headers) || {};
    let value;
    for (const name of Object.keys(headers)) {
        if (name.toLowerCase() === 'authorization') {
            value = headers[name];
            break;
        }
    }
    if (typeof value !== 'string') return null;
    const m = BEARER.exec(value.trim());
    if (!m || m[1].length > 200) return null;
    return m[1];
}

/**
 * Validates the bearer token. Returns { userId, email, name, expiresAt, tokenHash }
 * or throws 401 UNAUTHORIZED.
 */
async function requireSession(event) {
    const token = readBearerToken(event);
    if (!token) throw unauthorized();
    const tokenHash = hashToken(token);
    const res = await doc.send(new GetCommand({ TableName: process.env.SESSIONS_TABLE, Key: { tokenHash } }));
    const item = res.Item;
    if (!item || !item.expiresAt || Date.parse(item.expiresAt) <= Date.now()) throw unauthorized();
    return { userId: item.userId, email: item.email, name: item.name, expiresAt: item.expiresAt, tokenHash };
}

module.exports = { hashToken, readBearerToken, requireSession };
